const fs = require('fs');

const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/);
if (input.length < 5) process.exit(0);

let idx = 0;
const a = parseInt(input[idx++], 10);
const ta = parseInt(input[idx++], 10);
const b = parseInt(input[idx++], 10);
const tb = parseInt(input[idx++], 10);
const timeStr = input[idx++];

function toMinutes(t) {
    const [hh, mm] = t.split(':').map(Number);
    return hh * 60 + mm;
}

const startDay = 5 * 60;          // 05:00 in minutes
const endDay = 24 * 60 - 1;       // 23:59 in minutes

const simStart = toMinutes(timeStr);
const simEnd = simStart + ta;

// We need to count buses from B->A whose trip interval intersects (simStart, simEnd)
// Buses from B start at 05:00 and every b minutes, last start <= 23:59
let count = 0;

// Earliest departure from B
for (let dep = startDay; dep <= endDay; dep += b) {
    const arr = dep + tb;

    // Intersection of (simStart, simEnd) and [dep, arr]
    // Simion doesn't count encounters at exact start or finish:
    // so we need dep < simEnd and arr > simStart
    if (dep < simEnd && arr > simStart) {
        // But exclude encounters exactly at simStart or simEnd:
        // If the only intersection point is exactly simStart or simEnd,
        // then intervals just touch at boundary.
        // That corresponds to dep === simEnd or arr === simStart.
        if (!(dep === simEnd || arr === simStart)) {
            count++;
        }
    }
}

console.log(count.toString());
